mapper.select:
select 


order by ea.area_code, ei.item_code, ee.element_code, emi.management_item_code, prr.researcher_count, prr.participation_type, prr.effective_start_date desc
limit #{criteria.safeSize} offset #{criteria.offset}

select version_status
from evaluation_rule_versions
where rule_version_id = #{ruleVersionId}

select exists(
    select 1
    from evaluation_management_items emi
    inner join evaluation_elements ee on ee.element_id = emi.element_id
    inner join evaluation_items ei on ei.item_id = ee.item_id
    inner join evaluation_areas ea on ea.area_id = ei.area_id
    where emi.management_item_id = #{managementItemId}
      and ea.rule_version_id = #{ruleVersionId}
)

select 

where prr.rule_version_id = #{request.ruleVersionId}
  and prr.management_item_id = #{request.managementItemId}
  and prr.researcher_count = #{request.researcherCount}
  and prr.participation_type = #{request.participationType}
  and prr.effective_start_date = #{request.effectiveStartDate}
  and prr.effective_end_date = #{request.effectiveEndDate}
